insert into public.words (word, ipa, pos, meaning_vi, example, topic, order_index, study_term, example_vi, example_answer, example_source, source_note, dictionary_url, synonyms) values
('abide by', '/əˈbaɪd baɪ/', 'v', 'tuân thủ, tuân theo', 'All contractors must abide by the safety rules on site.', 'CONTRACTS (HỢP ĐỒNG)', 1, 'abide by', 'Tất cả nhà thầu phải tuân thủ các quy định an toàn tại công trường.', 'abide by', 'original', null, null, '[{"term":"comply with","pos":"v","meaning_vi":"tuân thủ","relation":"synonym","note_vi":null}]'),
('agreement', '/əˈɡriː.mənt/', 'n', 'sự thỏa thuận hợp đồng', 'Both companies signed the agreement after reviewing the payment terms.', 'CONTRACTS (HỢP ĐỒNG)', 2, 'agreement', 'Hai công ty đã ký thỏa thuận sau khi xem xét các điều khoản thanh toán.', 'agreement', 'original', null, null, '[{"term":"contract","pos":"n","meaning_vi":"hợp đồng","relation":"near","note_vi":"Contract là hợp đồng có tính ràng buộc pháp lý; agreement có thể chỉ thỏa thuận nói chung."}]'),
('assurance', '/əˈʃʊr.əns/', 'n', 'sự đảm bảo; lời cam đoan; sự tự tin', 'The supplier gave us assurance that the delivery would arrive on time.', 'CONTRACTS (HỢP ĐỒNG)', 3, 'assurance', 'Nhà cung cấp bảo đảm với chúng tôi rằng hàng sẽ được giao đúng hạn.', 'assurance', 'original', 'Cambridge xếp assurance là danh từ; PDF ghi thêm loại động từ.', 'https://dictionary.cambridge.org/us/dictionary/english/assurance', '[{"term":"guarantee","pos":"n","meaning_vi":"lời bảo đảm","relation":"near","note_vi":"Guarantee thường là cam kết chắc chắn hơn, đôi khi có ràng buộc pháp lý."}]'),
('cancellation', '/ˌkæn.səlˈeɪ.ʃən/', 'n', 'sự hủy bỏ, chấm dứt (n)', 'Please request cancellation before Friday to receive a full refund.', 'CONTRACTS (HỢP ĐỒNG)', 4, 'cancellation', 'Vui lòng yêu cầu hủy trước thứ Sáu để được hoàn tiền đầy đủ.', 'cancellation', 'original', null, null, '[{"term":"annulment","pos":"n","meaning_vi":"sự hủy bỏ hiệu lực","relation":"near","note_vi":"Annulment thường dùng cho quyết định hoặc thỏa thuận pháp lý, trang trọng hơn cancellation."}]'),
('determine', '/dɪˈtɜːrmɪn/', 'v', 'xác định', 'The inspection will determine whether the equipment needs urgent repairs.', 'CONTRACTS (HỢP ĐỒNG)', 5, 'determine', 'Cuộc kiểm tra sẽ xác định liệu thiết bị có cần sửa chữa khẩn cấp hay không.', 'determine', 'original', null, null, '[{"term":"ascertain","pos":"v","meaning_vi":"xác định, tìm cho rõ","relation":"synonym","note_vi":null}]'),
('engage', '/ɪnˈɡeɪdʒ/', 'v', 'tham dự', 'New employees can engage in discussions during the orientation workshop.', 'CONTRACTS (HỢP ĐỒNG)', 6, 'engage', 'Nhân viên mới có thể tham gia thảo luận trong buổi hướng dẫn hội nhập.', 'engage', 'original', null, null, '[{"term":"participate","pos":"v","meaning_vi":"tham gia","relation":"near","note_vi":"Trong nghĩa tham gia thảo luận, dùng participate in thay cho engage in."}]'),
('establish', '/ɪˈstæblɪʃ/', 'v', 'thành lập, thiết lập', 'Our partners plan to establish a regional office next spring.', 'CONTRACTS (HỢP ĐỒNG)', 7, 'establish', 'Các đối tác của chúng tôi dự định thành lập văn phòng khu vực vào mùa xuân tới.', 'establish', 'original', null, null, '[{"term":"set up","pos":"v","meaning_vi":"thành lập, thiết lập","relation":"synonym","note_vi":null}]'),
('obligate', '/ˈɑːblɪɡeɪt/', 'v', 'bắt buộc', 'These terms obligate the buyer to pay within thirty days.', 'CONTRACTS (HỢP ĐỒNG)', 8, 'obligate', 'Những điều khoản này buộc bên mua phải thanh toán trong vòng ba mươi ngày.', 'obligate', 'original', null, null, '[{"term":"oblige","pos":"v","meaning_vi":"buộc phải","relation":"synonym","note_vi":null}]'),
('party', '/ˈpɑːrti/', 'n', 'bên (trong các tổ chức)', 'Each party must keep a signed copy of the contract.', 'CONTRACTS (HỢP ĐỒNG)', 9, 'party', 'Mỗi bên phải giữ một bản hợp đồng đã ký.', 'party', 'original', null, null, '[{"term":"signatory","pos":"n","meaning_vi":"bên ký kết","relation":"near","note_vi":"Signatory là người hoặc tổ chức đã ký; party chỉ một bên liên quan, có thể chưa ký."}]'),
('provision', '/prəˈvɪʒ.ən/', 'n', 'sự cung cấp/ điều khoản', 'This provision allows customers to return damaged goods without charge.', 'CONTRACTS (HỢP ĐỒNG)', 10, 'provision', 'Điều khoản này cho phép khách hàng trả lại hàng hỏng mà không mất phí.', 'provision', 'original', null, null, '[{"term":"clause","pos":"n","meaning_vi":"điều khoản","relation":"synonym","note_vi":null}]'),
('resolve', '/rɪˈzɔːlv/', 'v', 'giải quyết, quyết định', 'The manager will resolve the billing dispute before the deadline.', 'CONTRACTS (HỢP ĐỒNG)', 11, 'resolve', 'Người quản lý sẽ giải quyết tranh chấp hóa đơn trước thời hạn.', 'resolve', 'original', null, null, '[{"term":"settle","pos":"v","meaning_vi":"giải quyết","relation":"synonym","note_vi":null}]'),
('specific', '/spəˈsɪf.ɪk/', 'adj', 'cụ thể', 'Please provide specific instructions for installing the new payment terminal.', 'CONTRACTS (HỢP ĐỒNG)', 12, 'specific', 'Vui lòng cung cấp hướng dẫn cụ thể để lắp đặt thiết bị thanh toán mới.', 'specific', 'original', null, null, '[{"term":"precise","pos":"adj","meaning_vi":"chính xác, rõ ràng","relation":"near","note_vi":"Precise nhấn mạnh độ chính xác; specific nhấn mạnh tính cụ thể."}]'),
('attract', '/əˈtrækt/', 'v', 'thu hút, hấp dẫn', 'The colorful window display should attract more customers this weekend.', 'MARKETING (TIẾP THỊ)', 13, 'attract', 'Cách trưng bày đầy màu sắc ở cửa sổ sẽ thu hút thêm khách hàng cuối tuần này.', 'attract', 'original', null, null, '[{"term":"draw","pos":"v","meaning_vi":"thu hút","relation":"synonym","note_vi":null}]'),
('compare', '/kəmˈper/', 'v', 'so sánh, đối chiếu', 'We should compare delivery fees before choosing an online supplier.', 'MARKETING (TIẾP THỊ)', 14, 'compare', 'Chúng ta nên so sánh phí giao hàng trước khi chọn nhà cung cấp trực tuyến.', 'compare', 'original', null, null, '[{"term":"contrast","pos":"v","meaning_vi":"đối chiếu điểm khác biệt","relation":"near","note_vi":"Contrast tập trung vào khác biệt; compare có thể xét cả điểm giống nhau."}]'),
('competition', '/ˌkɑːm.pəˈtɪʃ.ən/', 'n', 'sự cạnh tranh/ cuộc thi', 'Strong competition has encouraged local retailers to improve their service.', 'MARKETING (TIẾP THỊ)', 15, 'competition', 'Sự cạnh tranh mạnh mẽ đã khuyến khích các nhà bán lẻ địa phương cải thiện dịch vụ.', 'competition', 'original', null, null, '[{"term":"rivalry","pos":"n","meaning_vi":"sự cạnh tranh","relation":"synonym","note_vi":null}]'),
('consume', '/kən’sju:m/', 'v', 'tiêu thụ, sử dụng', 'Older printers consume more electricity than the models we ordered.', 'MARKETING (TIẾP THỊ)', 16, 'consume', 'Máy in cũ tiêu thụ nhiều điện hơn những mẫu chúng tôi đã đặt.', 'consume', 'original', null, null, '[{"term":"use up","pos":"v","meaning_vi":"tiêu thụ, dùng hết","relation":"near","note_vi":"Use up nhấn mạnh dùng hết; consume có thể chỉ sử dụng một phần năng lượng."}]'),
('convince', '/kənˈvɪns/', 'v', 'thuyết phục', 'The sales team hopes to convince customers to renew their subscriptions.', 'MARKETING (TIẾP THỊ)', 17, 'convince', 'Đội ngũ bán hàng hy vọng thuyết phục khách hàng gia hạn các gói đăng ký.', 'convince', 'original', null, null, '[{"term":"persuade","pos":"v","meaning_vi":"thuyết phục","relation":"synonym","note_vi":null}]'),
('inspiration', '/ˌɪn.spəˈreɪ.ʃən/', 'n', 'nguồn cảm hứng', 'Customer feedback provided the inspiration for our latest advertising campaign.', 'MARKETING (TIẾP THỊ)', 18, 'inspiration', 'Phản hồi của khách hàng mang lại cảm hứng cho chiến dịch quảng cáo mới nhất của chúng tôi.', 'inspiration', 'original', null, null, '[{"term":"stimulus","pos":"n","meaning_vi":"tác nhân khơi gợi","relation":"near","note_vi":"Stimulus thúc đẩy phản ứng hoặc ý tưởng; inspiration đặc biệt nhấn mạnh cảm hứng sáng tạo."}]'),
('market', '/ˈmɑːrkɪt/', 'v, n', 'buôn bán (v) thị trường (n)', 'The company entered the overseas market after extensive consumer research.', 'MARKETING (TIẾP THỊ)', 19, 'market', 'Công ty đã gia nhập thị trường nước ngoài sau khi nghiên cứu người tiêu dùng kỹ lưỡng.', 'market', 'original', null, null, '[{"term":"marketplace","pos":"n","meaning_vi":"thị trường","relation":"near","note_vi":"Marketplace nhấn mạnh môi trường mua bán; market còn có thể chỉ nhóm khách hàng hoặc nhu cầu."}]'),
('persuasion', '/pəˈsweɪ.ʒən/', 'n', 'sự thuyết phục', 'It took considerable persuasion to secure approval for the revised budget.', 'MARKETING (TIẾP THỊ)', 20, 'persuasion', 'Phải thuyết phục rất nhiều mới được phê duyệt ngân sách đã điều chỉnh.', 'persuasion', 'original', null, null, '[{"term":"convincing","pos":"n","meaning_vi":"việc thuyết phục","relation":"synonym","note_vi":null}]'),
('productive', '/prəˈdʌk.tɪv/', 'adj', 'năng suất | có hiệu quả, có năng suất', 'Our morning meeting was productive because everyone arrived fully prepared.', 'MARKETING (TIẾP THỊ) | PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 21, 'productive', 'Cuộc họp sáng của chúng tôi hiệu quả vì mọi người đều đến với sự chuẩn bị đầy đủ.', 'productive', 'original', null, null, '[{"term":"fruitful","pos":"adj","meaning_vi":"mang lại kết quả tốt","relation":"synonym","note_vi":null}]'),
('satisfaction', '/ˌsæt.ɪsˈfæk.ʃən/', 'n', 'sự hài lòng, thỏa mãn', 'The survey measures customer satisfaction with our new delivery service.', 'MARKETING (TIẾP THỊ)', 22, 'satisfaction', 'Cuộc khảo sát đo lường mức độ hài lòng của khách hàng với dịch vụ giao hàng mới.', 'satisfaction', 'original', null, null, '[{"term":"contentment","pos":"n","meaning_vi":"sự mãn nguyện","relation":"near","note_vi":"Contentment thường chỉ trạng thái hài lòng nói chung, ít dùng làm chỉ số dịch vụ khách hàng."}]'),
('currently', '/ˈkɝː.ənt.li/', 'adv', 'hiện thời, hiện nay', 'The downtown branch is currently closed for essential electrical repairs.', 'MARKETING (TIẾP THỊ)', 23, 'currently', 'Chi nhánh trung tâm hiện đang đóng cửa để sửa chữa hệ thống điện cần thiết.', 'currently', 'original', null, null, '[{"term":"at present","pos":"adv","meaning_vi":"hiện nay","relation":"synonym","note_vi":null}]'),
('fad', '/fæd/', 'n', 'mốt nhất thời', 'Management considers the new packaging style a temporary marketing fad.', 'MARKETING (TIẾP THỊ)', 24, 'fad', 'Ban quản lý xem kiểu bao bì mới là một trào lưu tiếp thị nhất thời.', 'fad', 'original', null, null, '[{"term":"craze","pos":"n","meaning_vi":"cơn sốt nhất thời","relation":"near","note_vi":"Craze thường hàm ý sự yêu thích cuồng nhiệt hơn fad."}]'),
('characteristic', '/ˌker.ək.təˈrɪs.tɪk/', 'adj, n', 'đặc thù (adj) đặc trưng, đặc điểm (n)', 'Reliability is the most important characteristic of this industrial printer.', 'WARRANTIES (BẢO HÀNH)', 25, 'characteristic', 'Độ tin cậy là đặc điểm quan trọng nhất của máy in công nghiệp này.', 'characteristic', 'original', null, null, '[{"term":"feature","pos":"n","meaning_vi":"đặc điểm","relation":"synonym","note_vi":null}]'),
('consequence', '/ˈkɑːnsɪkwens/', 'n', 'kết quả, hậu quả', 'A possible consequence of late payment is suspension of service.', 'WARRANTIES (BẢO HÀNH)', 26, 'consequence', 'Một hậu quả có thể xảy ra khi thanh toán trễ là bị ngừng dịch vụ.', 'consequence', 'original', null, null, '[{"term":"result","pos":"n","meaning_vi":"kết quả","relation":"synonym","note_vi":null}]'),
('cover', '/ˈkʌvər/', 'v', 'che phủ, bao gồm', 'The warranty will cover repairs during the first twelve months.', 'WARRANTIES (BẢO HÀNH)', 27, 'cover', 'Chế độ bảo hành sẽ bao gồm việc sửa chữa trong mười hai tháng đầu tiên.', 'cover', 'original', null, null, '[{"term":"include","pos":"v","meaning_vi":"bao gồm","relation":"synonym","note_vi":null}]'),
('expiration', '/ˌek.spəˈreɪ.ʃən/', 'n', 'sự hết hạn', 'Check the expiration date before accepting the supplier''s discount offer.', 'WARRANTIES (BẢO HÀNH)', 28, 'expiration', 'Hãy kiểm tra ngày hết hạn trước khi chấp nhận ưu đãi giảm giá của nhà cung cấp.', 'expiration', 'original', null, null, '[{"term":"expiry","pos":"n","meaning_vi":"sự hết hạn","relation":"synonym","note_vi":null}]'),
('frequently', '/ˈfriːkwəntli/', 'adv', 'thường xuyên', 'Our technicians frequently inspect the elevators to prevent unexpected breakdowns.', 'WARRANTIES (BẢO HÀNH)', 29, 'frequently', 'Các kỹ thuật viên của chúng tôi thường xuyên kiểm tra thang máy để tránh hỏng hóc bất ngờ.', 'frequently', 'original', null, null, '[{"term":"often","pos":"adv","meaning_vi":"thường xuyên","relation":"synonym","note_vi":null}]'),
('imply', '/ɪmˈplaɪ/', 'v', 'ngụ ý, hàm ý', 'The brochure does not imply that accidental damage is covered.', 'WARRANTIES (BẢO HÀNH)', 30, 'imply', 'Tờ giới thiệu không ngụ ý rằng hư hỏng do tai nạn được bảo hành.', 'imply', 'original', null, null, '[{"term":"suggest","pos":"v","meaning_vi":"hàm ý, gợi ra","relation":"synonym","note_vi":null}]'),
('promise', '/ˈprɑːmɪs/', 'n, v', 'lời hứa, sự cam đoan (n) hứa, cam kết (v)', 'We promise to replace defective products within five business days.', 'WARRANTIES (BẢO HÀNH)', 31, 'promise', 'Chúng tôi cam kết thay thế sản phẩm lỗi trong vòng năm ngày làm việc.', 'promise', 'original', null, null, '[{"term":"pledge","pos":"v","meaning_vi":"cam kết","relation":"near","note_vi":"Pledge trang trọng và nhấn mạnh sự cam kết hơn promise."}]'),
('reputation', '/ˌrepjuˈteɪʃn/', 'n', 'danh tiếng, thanh danh', 'The hotel built its reputation on attentive service and spotless rooms.', 'WARRANTIES (BẢO HÀNH)', 32, 'reputation', 'Khách sạn xây dựng danh tiếng nhờ dịch vụ chu đáo và các phòng sạch tinh tươm.', 'reputation', 'original', null, null, '[{"term":"standing","pos":"n","meaning_vi":"danh tiếng, vị thế","relation":"near","note_vi":"Standing thường nhấn mạnh mức độ được kính trọng trong một cộng đồng hoặc ngành."}]'),
('require', '/rɪˈkwaɪər/', 'v', 'đòi hỏi, yêu cầu', 'Most repair requests require a receipt and the original warranty certificate.', 'WARRANTIES (BẢO HÀNH)', 33, 'require', 'Hầu hết yêu cầu sửa chữa đều cần biên lai và giấy bảo hành gốc.', 'require', 'original', null, null, '[{"term":"need","pos":"v","meaning_vi":"cần","relation":"synonym","note_vi":null}]'),
('variety', '/vəˈraɪəti/', 'n', 'sự đa dạng', 'The store offers a wide variety of replacement computer accessories.', 'WARRANTIES (BẢO HÀNH)', 34, 'variety', 'Cửa hàng cung cấp nhiều loại phụ kiện máy tính thay thế đa dạng.', 'variety', 'original', null, null, '[{"term":"range","pos":"n","meaning_vi":"loạt, nhiều loại","relation":"synonym","note_vi":null}]'),
('address', '/əˈdres/', 'v, n', 'trình bày, nhấn mạnh (v) bài diễn văn (n)', 'The director delivered a brief address at the annual planning conference.', 'BUSINESS PLANNING (KẾ HOẠCH KINH DOANH)', 35, 'address', 'Giám đốc đã có một bài phát biểu ngắn tại hội nghị lập kế hoạch hằng năm.', 'address', 'original', null, null, '[{"term":"speech","pos":"n","meaning_vi":"bài phát biểu","relation":"synonym","note_vi":null}]'),
('avoid', '/əˈvɔɪd/', 'v', 'phòng tránh, ngăn ngừa', 'Schedule regular equipment checks to avoid costly interruptions during production.', 'BUSINESS PLANNING (KẾ HOẠCH KINH DOANH)', 36, 'avoid', 'Hãy lên lịch kiểm tra thiết bị định kỳ để tránh gián đoạn tốn kém trong sản xuất.', 'avoid', 'original', null, null, '[{"term":"prevent","pos":"v","meaning_vi":"ngăn ngừa","relation":"near","note_vi":"Prevent nhấn mạnh ngăn sự việc xảy ra; avoid còn có thể là chủ động tránh gặp sự việc."}]'),
('demonstrate', '/ˈdemənstreɪt/', 'v', 'chứng minh, giải thích', 'These figures demonstrate the benefits of investing in staff development.', 'BUSINESS PLANNING (KẾ HOẠCH KINH DOANH)', 37, 'demonstrate', 'Những số liệu này chứng minh lợi ích của việc đầu tư vào phát triển nhân viên.', 'demonstrate', 'original', null, null, '[{"term":"show","pos":"v","meaning_vi":"cho thấy, chứng tỏ","relation":"synonym","note_vi":null}]'),
('develop', '/dɪˈveləp/', 'v', 'phát triển', 'The research team will develop a cheaper manufacturing process next year.', 'BUSINESS PLANNING (KẾ HOẠCH KINH DOANH)', 38, 'develop', 'Nhóm nghiên cứu sẽ phát triển một quy trình sản xuất ít tốn kém hơn vào năm tới.', 'develop', 'original', null, null, '[{"term":"create","pos":"v","meaning_vi":"tạo ra","relation":"near","note_vi":"Create nhấn mạnh tạo ra điều mới; develop thường bao gồm quá trình xây dựng và cải tiến."}]'),
('evaluate', '/ɪˈvæljueɪt/', 'v', 'đánh giá, ước lượng', 'We need to evaluate several proposals before selecting a contractor.', 'BUSINESS PLANNING (KẾ HOẠCH KINH DOANH)', 39, 'evaluate', 'Chúng ta cần đánh giá một số đề xuất trước khi chọn nhà thầu.', 'evaluate', 'original', null, null, '[{"term":"assess","pos":"v","meaning_vi":"đánh giá","relation":"synonym","note_vi":null}]'),
('gather', '/ˈɡæðər/', 'v', 'tập hợp, thu thập', 'Please gather the latest sales figures before tomorrow''s planning meeting.', 'BUSINESS PLANNING (KẾ HOẠCH KINH DOANH)', 40, 'gather', 'Vui lòng thu thập số liệu bán hàng mới nhất trước cuộc họp lập kế hoạch ngày mai.', 'gather', 'original', null, null, '[{"term":"collect","pos":"v","meaning_vi":"thu thập","relation":"synonym","note_vi":null}]'),
('offer', '/ˈɔːfər/', 'n, v', 'đề xuất, đề nghị (n,v)', 'The board accepted our offer to manage the new distribution center.', 'BUSINESS PLANNING (KẾ HOẠCH KINH DOANH)', 41, 'offer', 'Hội đồng quản trị đã chấp nhận đề nghị quản lý trung tâm phân phối mới của chúng tôi.', 'offer', 'original', null, null, '[{"term":"proposal","pos":"n","meaning_vi":"đề xuất","relation":"near","note_vi":"Proposal có thể là kế hoạch chi tiết; offer thường là lời đề nghị cung cấp hoặc thực hiện việc gì."}]'),
('primarily', '/praɪˈmerəli/', 'adv', 'ưu tiên, chủ yếu', 'The campaign is aimed primarily at small businesses in rural areas.', 'BUSINESS PLANNING (KẾ HOẠCH KINH DOANH)', 42, 'primarily', 'Chiến dịch chủ yếu hướng đến các doanh nghiệp nhỏ ở khu vực nông thôn.', 'primarily', 'original', null, null, '[{"term":"mainly","pos":"adv","meaning_vi":"chủ yếu","relation":"synonym","note_vi":null}]'),
