('flexibly', '/ˈflek.sə.bli/', 'adv', 'một cách linh hoạt', 'Our new policy allows parents to arrange their working hours flexibly.', 'SALARIES AND BENEFITS (LƯƠNG VÀ PHÚC LỢI)', 162, 'flexibly', 'Chính sách mới của chúng tôi cho phép phụ huynh sắp xếp giờ làm việc linh hoạt.', 'flexibly', 'original', null, null, '[{"term":"adaptably","pos":"adv","meaning_vi":"một cách linh hoạt, dễ thích ứng","relation":"near","note_vi":"Adaptably nhấn mạnh khả năng thích ứng; flexibly còn chỉ cách sắp xếp có thể thay đổi."}]'),
('negotiate', '/nɪˈɡoʊʃieɪt/', 'v', 'đàm phán, thương lượng', 'The union will negotiate higher wages with management next week.', 'SALARIES AND BENEFITS (LƯƠNG VÀ PHÚC LỢI)', 163, 'negotiate', 'Công đoàn sẽ thương lượng mức lương cao hơn với ban quản lý vào tuần tới.', 'negotiate', 'original', null, null, '[{"term":"bargain","pos":"v","meaning_vi":"thương lượng","relation":"near","note_vi":"Bargain thường tập trung vào giá cả hoặc điều kiện trao đổi; negotiate có phạm vi rộng hơn."}]'),
('retire', '/rɪˈtaɪər/', 'v', 'nghỉ hưu', 'Our senior accountant plans to retire at the end of June.', 'SALARIES AND BENEFITS (LƯƠNG VÀ PHÚC LỢI)', 164, 'retire', 'Kế toán viên cao cấp của chúng tôi dự định nghỉ hưu vào cuối tháng Sáu.', 'retire', 'original', null, null, '[{"term":"leave the workforce","pos":"v","meaning_vi":"nghỉ làm, rời lực lượng lao động","relation":"near","note_vi":"Retire thường là nghỉ hưu; leave the workforce còn có thể là tạm nghỉ vì lý do khác."}]'),
('vested', '/ˈvestɪd/', 'adj', 'giao cho, ban cho', 'Authority to approve pension payments is vested in the finance director.', 'SALARIES AND BENEFITS (LƯƠNG VÀ PHÚC LỢI)', 165, 'vested', 'Quyền phê duyệt chi trả lương hưu được trao cho giám đốc tài chính.', 'vested', 'original', null, null, '[{"term":"conferred","pos":"adj","meaning_vi":"được trao","relation":"near","note_vi":"Vested in nhấn mạnh quyền chính thức thuộc về ai; dùng conferred on khi nói quyền được trao cho ai."}]'),
('wage', '/weɪdʒ/', 'n', 'lương theo giờ', 'The starting hourly wage will increase after the probationary period.', 'SALARIES AND BENEFITS (LƯƠNG VÀ PHÚC LỢI)', 166, 'wage', 'Mức lương theo giờ ban đầu sẽ tăng sau thời gian thử việc.', 'wage', 'original', null, null, '[{"term":"pay","pos":"n","meaning_vi":"tiền công","relation":"near","note_vi":"Pay là tiền công nói chung; wage thường được tính theo giờ hoặc tuần."}]'),
('raise', '/reɪz/', 'n, v', 'tăng lên (v) sự tăng trưởng (n)', 'Management agreed to raise salaries following the annual performance reviews.', 'SALARIES AND BENEFITS (LƯƠNG VÀ PHÚC LỢI)', 167, 'raise', 'Ban quản lý đồng ý tăng lương sau các đợt đánh giá hiệu suất hằng năm.', 'raise', 'original', null, null, '[{"term":"increase","pos":"v","meaning_vi":"tăng","relation":"synonym","note_vi":null}]'),
('achievement', '/əˈtʃiːv.mənt/', 'n', 'thành tựu (= accomplishment)', 'Winning the regional sales award was a significant achievement for our team.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 168, 'achievement', 'Việc giành giải thưởng bán hàng khu vực là một thành tựu quan trọng của đội chúng tôi.', 'achievement', 'original', null, null, '[{"term":"accomplishment","pos":"n","meaning_vi":"thành tựu","relation":"synonym","note_vi":null}]'),
('contribute', '/kənˈtrɪbjuːt/', 'v', 'đóng góp', 'Experienced employees can contribute valuable ideas during the planning workshop.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 169, 'contribute', 'Những nhân viên giàu kinh nghiệm có thể đóng góp các ý tưởng quý giá trong hội thảo lập kế hoạch.', 'contribute', 'original', null, null, '[{"term":"provide","pos":"v","meaning_vi":"đóng góp, cung cấp","relation":"near","note_vi":"Provide nhấn mạnh cung cấp; contribute nhấn mạnh thêm phần của mình vào nỗ lực chung."}]'),
('dedication', '/ˌded.ɪˈkeɪ.ʃən/', 'n', 'sự cống hiến', 'Her dedication to customer service earned her the employee award.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 170, 'dedication', 'Sự tận tâm với dịch vụ khách hàng đã giúp cô ấy giành giải thưởng nhân viên.', 'dedication', 'original', null, null, '[{"term":"commitment","pos":"n","meaning_vi":"sự tận tâm, cam kết","relation":"synonym","note_vi":null}]'),
('looking forward to V-ing', '/lʊk ˈfɔːrwərd tuː/', 'v', 'trông mong, mong đợi', 'We look forward to celebrating your promotion at Friday''s reception.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 171, 'look forward to', 'Chúng tôi mong được chúc mừng việc thăng chức của bạn tại buổi tiệc chiêu đãi thứ Sáu.', 'look forward to', 'original', 'Dạng học là look forward to; sau to dùng danh từ hoặc động từ thêm -ing.', 'https://dictionary.cambridge.org/grammar/british-grammar/look-forward-to', '[{"term":"eagerly anticipate","pos":"v","meaning_vi":"háo hức mong đợi","relation":"near","note_vi":"Anticipate có thể theo sau trực tiếp bằng danh từ hoặc V-ing, không dùng to như look forward to."}]'),
('look to', '/lʊk tuː/', 'v', 'trông cậy vào ai', 'New team leaders often look to experienced managers for guidance.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 172, 'look to', 'Các trưởng nhóm mới thường trông cậy vào quản lý giàu kinh nghiệm để được hướng dẫn.', 'look to', 'original', null, null, '[{"term":"rely on","pos":"v","meaning_vi":"trông cậy vào","relation":"synonym","note_vi":null}]'),
('loyal', '/ˈlɔɪ.əl/', 'adj', 'trung thành', 'The company rewards loyal employees with additional vacation days.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 173, 'loyal', 'Công ty thưởng cho các nhân viên trung thành bằng những ngày nghỉ phép bổ sung.', 'loyal', 'original', null, null, '[{"term":"faithful","pos":"adj","meaning_vi":"trung thành","relation":"synonym","note_vi":null}]'),
('merit', '/ˈmerɪt/', 'n', 'công lao, tài giỏi', 'Promotions should be based on merit rather than personal connections.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 174, 'merit', 'Việc thăng chức nên dựa trên năng lực thay vì các mối quan hệ cá nhân.', 'merit', 'original', null, null, '[{"term":"worthiness","pos":"n","meaning_vi":"giá trị, sự xứng đáng","relation":"near","note_vi":"Merit trong tuyển dụng nhấn mạnh năng lực hoặc thành tích xứng đáng; worthiness có nghĩa rộng hơn."}]'),
('obviously', '/ˈɑːb.vi.əs.li/', 'adv', 'rõ ràng, hiển nhiên', 'The improved sales figures obviously pleased the entire management team.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 175, 'obviously', 'Số liệu bán hàng được cải thiện rõ ràng đã làm cả đội ngũ quản lý hài lòng.', 'obviously', 'original', null, null, '[{"term":"clearly","pos":"adv","meaning_vi":"rõ ràng","relation":"synonym","note_vi":null}]'),
('promote', '/prəˈməʊt/', 'v', 'đẩy mạnh/ thăng chức', 'The board intends to promote her to regional director next month.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 176, 'promote', 'Hội đồng quản trị dự định thăng chức cô ấy lên giám đốc khu vực vào tháng tới.', 'promote', 'original', null, null, '[{"term":"advance","pos":"v","meaning_vi":"thăng chức, đưa lên vị trí cao hơn","relation":"near","note_vi":"Advance còn có thể chỉ sự tiến bộ; promote nhấn mạnh trao chức vụ cao hơn."}]'),
('recognition', '/ˌrek.əɡˈnɪʃ.ən/', 'n', 'sự công nhận', 'The award provides recognition for outstanding contributions to workplace safety.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 177, 'recognition', 'Giải thưởng ghi nhận những đóng góp xuất sắc cho an toàn tại nơi làm việc.', 'recognition', 'original', null, null, '[{"term":"acknowledgment","pos":"n","meaning_vi":"sự ghi nhận","relation":"synonym","note_vi":null}]'),
('value', '/ˈvæljuː/', 'n, v', 'định giá (v) giá trị (n)', 'An independent consultant will value the equipment before the sale.', 'PROMOTIONS, PENSIONS AND AWARDS (THĂNG TIẾN, LƯƠNG HƯU VÀ GIẢI THƯỞNG)', 178, 'value', 'Một chuyên gia tư vấn độc lập sẽ định giá thiết bị trước khi bán.', 'value', 'original', null, null, '[{"term":"appraise","pos":"v","meaning_vi":"định giá","relation":"synonym","note_vi":null}]'),
('bargain', '/ˈbɑːrɡən/', 'n, v', 'món hời (n) mặc cả (v)', 'This discounted office chair is a bargain compared with similar models.', 'SHOPPING (MUA SẮM)', 179, 'bargain', 'Chiếc ghế văn phòng giảm giá này là một món hời so với các mẫu tương tự.', 'bargain', 'original', null, null, '[{"term":"good deal","pos":"n","meaning_vi":"món hời","relation":"synonym","note_vi":null}]'),
('bear', '/ber/', 'v', 'chịu đựng, cam chịu', 'Customers should not have to bear long waits at the checkout.', 'SHOPPING (MUA SẮM)', 180, 'bear', 'Khách hàng không đáng phải chịu cảnh chờ đợi lâu tại quầy thanh toán.', 'bear', 'original', null, null, '[{"term":"endure","pos":"v","meaning_vi":"chịu đựng","relation":"synonym","note_vi":null}]'),
('behavior', '/bɪˈheɪ.vjər/', 'n', 'thái độ, hành vi', 'The supervisor spoke to the cashier about her rude behavior.', 'SHOPPING (MUA SẮM)', 181, 'behavior', 'Người giám sát đã trao đổi với thu ngân về hành vi bất lịch sự của cô ấy.', 'behavior', 'original', null, null, '[{"term":"conduct","pos":"n","meaning_vi":"hành vi, cách cư xử","relation":"synonym","note_vi":null}]'),
('checkout', '/tʃek aʊt əv/', 'n', 'quầy thanh toán, thủ tục thanh toán', 'Please take your purchases to the checkout near the main entrance.', 'SHOPPING (MUA SẮM)', 182, 'checkout', 'Vui lòng mang hàng đã chọn đến quầy thanh toán gần lối vào chính.', 'checkout', 'original', null, null, '[{"term":"payment counter","pos":"n","meaning_vi":"quầy thanh toán","relation":"synonym","note_vi":null}]'),
('comfort', '/ˈkʌmfərt/', 'n, v', 'sự thoải mái (n) an ủi (v)', 'The spacious waiting area provides comfort for tired shoppers.', 'SHOPPING (MUA SẮM)', 183, 'comfort', 'Khu vực chờ rộng rãi mang lại sự thoải mái cho những người mua sắm mệt mỏi.', 'comfort', 'original', null, null, '[{"term":"ease","pos":"n","meaning_vi":"sự thoải mái","relation":"synonym","note_vi":null}]'),
('expand', '/ɪkˈspænd', 'v', 'mở rộng', 'The retailer plans to expand its online selection next season.', 'SHOPPING (MUA SẮM)', 184, 'expand', 'Nhà bán lẻ dự định mở rộng danh mục hàng trực tuyến vào mùa tới.', 'expand', 'original', null, null, '[{"term":"broaden","pos":"v","meaning_vi":"mở rộng","relation":"synonym","note_vi":null}]'),
('explore', '/ɪkˈsplɔːr/', 'v', 'khám phá, thăm dò', 'We should explore other suppliers before ordering new display shelves.', 'SHOPPING (MUA SẮM)', 185, 'explore', 'Chúng ta nên tìm hiểu các nhà cung cấp khác trước khi đặt kệ trưng bày mới.', 'explore', 'original', null, null, '[{"term":"investigate","pos":"v","meaning_vi":"tìm hiểu, khảo sát","relation":"synonym","note_vi":null}]'),
('item', '/ˈaɪtəm/', 'n', 'món hàng, món đồ', 'Each item in the clearance section has a red price tag.', 'SHOPPING (MUA SẮM)', 186, 'item', 'Mỗi món hàng trong khu thanh lý đều có nhãn giá màu đỏ.', 'item', 'original', null, null, '[{"term":"article","pos":"n","meaning_vi":"món đồ","relation":"synonym","note_vi":null}]'),
('mandatory', '/ˈmændətɔːri/', 'adj', 'bắt buộc', 'Wearing protective gloves is mandatory when handling these cleaning products.', 'SHOPPING (MUA SẮM)', 187, 'mandatory', 'Việc đeo găng tay bảo hộ là bắt buộc khi xử lý những sản phẩm tẩy rửa này.', 'mandatory', 'original', null, null, '[{"term":"compulsory","pos":"adj","meaning_vi":"bắt buộc","relation":"synonym","note_vi":null}]'),
('merchandise', '/ˈmɜːrtʃəndaɪz/', 'n', 'hàng hóa (= goods)', 'The store will display seasonal merchandise near the front windows.', 'SHOPPING (MUA SẮM)', 188, 'merchandise', 'Cửa hàng sẽ trưng bày hàng hóa theo mùa gần các cửa sổ phía trước.', 'merchandise', 'original', null, null, '[{"term":"goods","pos":"n","meaning_vi":"hàng hóa","relation":"synonym","note_vi":null}]'),
('strictly', '/ˈstrɪkt.li/', 'adv', 'một cách nghiêm khắc', 'The store strictly enforces its policy on returns without receipts.', 'SHOPPING (MUA SẮM)', 189, 'strictly', 'Cửa hàng thực thi nghiêm ngặt chính sách trả hàng không có biên lai.', 'strictly', 'original', null, null, '[{"term":"rigorously","pos":"adv","meaning_vi":"một cách nghiêm ngặt","relation":"synonym","note_vi":null}]'),
('trend', '/trend/', 'n', 'xu hướng', 'The latest shopping trend favors reusable bags and minimal packaging.', 'SHOPPING (MUA SẮM)', 190, 'trend', 'Xu hướng mua sắm mới nhất ưu tiên túi tái sử dụng và bao bì tối giản.', 'trend', 'original', null, null, '[{"term":"tendency","pos":"n","meaning_vi":"xu hướng","relation":"near","note_vi":"Tendency có thể là khuynh hướng hành vi; trend thường là hướng thay đổi được nhiều người thể hiện."}]'),
('diversify', '/daɪˈvɜːrsɪfaɪ/', 'v', 'đa dạng hóa', 'We plan to diversify our suppliers to reduce delivery risks.', 'ORDERING SUPPLIES (ĐẶT HÀNG NHÀ CUNG CẤP)', 191, 'diversify', 'Chúng tôi dự định đa dạng hóa nhà cung cấp để giảm rủi ro giao hàng.', 'diversify', 'original', null, null, '[{"term":"broaden the range of","pos":"v","meaning_vi":"đa dạng hóa, mở rộng phạm vi","relation":"near","note_vi":"Cụm này nhấn mạnh mở rộng chủng loại; diversify còn nhấn mạnh tạo nhiều nguồn hoặc lĩnh vực khác nhau."}]'),
('consistent', '/kənˈsɪstənt/', 'adj', 'đều đặn, nhất quán', 'Our purchasing team expects consistent quality from every approved supplier.', 'ORDERING SUPPLIES (ĐẶT HÀNG NHÀ CUNG CẤP)', 192, 'consistent', 'Đội ngũ mua hàng của chúng tôi mong đợi chất lượng nhất quán từ mọi nhà cung cấp được phê duyệt.', 'consistent', 'original', null, null, '[{"term":"uniform","pos":"adj","meaning_vi":"đồng nhất","relation":"near","note_vi":"Uniform nhấn mạnh giống nhau giữa các sản phẩm; consistent còn nhấn mạnh ổn định qua thời gian."}]'),
('enterprise', '/ˈentərpraɪz/', 'n', 'dự án lớn/ doanh nghiệp', 'The family enterprise now supplies furniture to hotels across the region.', 'ORDERING SUPPLIES (ĐẶT HÀNG NHÀ CUNG CẤP)', 193, 'enterprise', 'Doanh nghiệp gia đình hiện cung cấp nội thất cho các khách sạn khắp khu vực.', 'enterprise', 'original', null, null, '[{"term":"business","pos":"n","meaning_vi":"doanh nghiệp","relation":"synonym","note_vi":null}]'),
('essentially', '/ɪˈsen.ʃəl.i/', 'adv', 'một cách thiết yếu, về cơ bản', 'The two purchasing proposals are essentially the same despite different wording.', 'ORDERING SUPPLIES (ĐẶT HÀNG NHÀ CUNG CẤP)', 194, 'essentially', 'Hai đề xuất mua hàng về cơ bản giống nhau dù cách diễn đạt khác nhau.', 'essentially', 'original', null, null, '[{"term":"basically","pos":"adv","meaning_vi":"về cơ bản","relation":"synonym","note_vi":null}]'),
('function', '/ˈfʌŋkʃn/', 'n, v', 'hoạt động (v) nhiệm vụ, mục tiêu (n)', 'The warehouse cannot function efficiently without accurate inventory records.', 'ORDERING SUPPLIES (ĐẶT HÀNG NHÀ CUNG CẤP)', 195, 'function', 'Nhà kho không thể hoạt động hiệu quả nếu thiếu hồ sơ hàng tồn kho chính xác.', 'function', 'original', null, null, '[{"term":"operate","pos":"v","meaning_vi":"hoạt động","relation":"synonym","note_vi":null}]'),
('maintain', '/meɪnˈteɪn/', 'v', 'duy trì', 'Regular deliveries help us maintain adequate supplies throughout the month.', 'ORDERING SUPPLIES (ĐẶT HÀNG NHÀ CUNG CẤP)', 196, 'maintain', 'Việc giao hàng đều đặn giúp chúng tôi duy trì đủ vật tư trong suốt tháng.', 'maintain', 'original', null, null, '[{"term":"sustain","pos":"v","meaning_vi":"duy trì","relation":"synonym","note_vi":null}]'),
('obtain', '/əbˈteɪn/', 'v', 'đạt được, giành được', 'Please obtain written approval before ordering any replacement machinery.', 'ORDERING SUPPLIES (ĐẶT HÀNG NHÀ CUNG CẤP)', 197, 'obtain', 'Vui lòng xin phê duyệt bằng văn bản trước khi đặt bất kỳ máy móc thay thế nào.', 'obtain', 'original', null, null, '[{"term":"get","pos":"v","meaning_vi":"có được, đạt được","relation":"synonym","note_vi":null}]'),
('prerequisite', '/ˌpriːˈrekwəzɪt/', 'n', 'điều kiện tiên quyết', 'A valid purchase order is a prerequisite for processing your request.', 'ORDERING SUPPLIES (ĐẶT HÀNG NHÀ CUNG CẤP)', 198, 'prerequisite', 'Một đơn đặt hàng hợp lệ là điều kiện tiên quyết để xử lý yêu cầu của bạn.', 'prerequisite', 'original', null, null, '[{"term":"precondition","pos":"n","meaning_vi":"điều kiện tiên quyết","relation":"synonym","note_vi":null}]'),
