('entertain', '/ˌentərˈteɪn/', 'v', 'giải trí', 'The hotel hired a magician to entertain guests during the reception.', 'MOVIES (PHIM ẢNH)', 486, 'entertain', 'Khách sạn thuê một ảo thuật gia để giúp khách giải trí trong buổi tiệc đón tiếp.', 'entertain', 'original', null, null, '[{"term":"amuse","pos":"v","meaning_vi":"làm vui, giúp giải trí","relation":"near","note_vi":"Amuse thiên về gây thích thú hoặc buồn cười; entertain bao gồm nhiều hình thức giải trí."}]'),
('influence', '/ˈɪnfluəns/', 'n, v', 'sự ảnh hưởng (n) gây ảnh hưởng (v)', 'Positive reviews can influence customers when they choose a film to watch.', 'MOVIES (PHIM ẢNH)', 487, 'influence', 'Những bài đánh giá tích cực có thể ảnh hưởng đến khách khi họ chọn phim để xem.', 'influence', 'original', null, null, '[{"term":"affect","pos":"v","meaning_vi":"ảnh hưởng đến","relation":"synonym","note_vi":null}]'),
('range', '/reɪndʒ/', 'n', 'phạm vi', 'The entertainment package offers a wide range of films and documentaries.', 'MOVIES (PHIM ẢNH)', 488, 'range', 'Gói giải trí cung cấp nhiều loại phim truyện và phim tài liệu.', 'range', 'original', null, null, '[{"term":"variety","pos":"n","meaning_vi":"sự đa dạng, nhiều loại","relation":"near","note_vi":"Phù hợp với a wide range of; range còn có nghĩa phạm vi hoặc giới hạn."}]'),
('release', '/rɪˈliːs/', 'v, n', 'công chiếu (v) sự công chiếu (n)', 'The studio will release its latest film in cinemas next month.', 'MOVIES (PHIM ẢNH)', 489, 'release', 'Hãng phim sẽ công chiếu bộ phim mới nhất tại các rạp vào tháng tới.', 'release', 'original', null, null, '[{"term":"bring out","pos":"v","meaning_vi":"phát hành","relation":"near","note_vi":"Dùng cho phim, sách, sản phẩm; không dùng cho mọi nghĩa giải phóng của release."}]'),
('represent', '/ˌreprɪˈzent/', 'v', 'tượng trưng, đại diện', 'These photographs represent important moments in the history of local cinema.', 'MOVIES (PHIM ẢNH)', 490, 'represent', 'Những bức ảnh này tượng trưng cho các thời điểm quan trọng trong lịch sử điện ảnh địa phương.', 'represent', 'original', null, null, '[{"term":"depict","pos":"v","meaning_vi":"miêu tả, thể hiện","relation":"near","note_vi":"Dùng khi ảnh thể hiện sự kiện; represent còn có nghĩa đại diện."}]'),
('separate', '/ˈsepəreɪt/', 'adj, v', 'riêng biệt (adj) tách rời, chia (v)', 'The cinema has a separate entrance for guests attending private screenings.', 'MOVIES (PHIM ẢNH)', 491, 'separate', 'Rạp phim có lối vào riêng cho khách tham dự các buổi chiếu riêng.', 'separate', 'original', null, null, '[{"term":"distinct","pos":"adj","meaning_vi":"riêng biệt","relation":"synonym","note_vi":null}]'),
('successive', '/səkˈsesiv/', 'adj', 'liên tiếp', 'The documentary won awards at three successive international film festivals.', 'MOVIES (PHIM ẢNH)', 492, 'successive', 'Bộ phim tài liệu giành giải tại ba liên hoan phim quốc tế liên tiếp.', 'successive', 'original', null, null, '[{"term":"consecutive","pos":"adj","meaning_vi":"liên tiếp","relation":"synonym","note_vi":null}]'),
('action', '/ˈæk.ʃən/', 'n', 'hành động; diễn biến (trong phim hoặc câu chuyện)', 'The director asked the crew to prepare for the next action scene.', 'THEATER (RẠP PHIM)', 493, 'action', 'Đạo diễn yêu cầu đoàn phim chuẩn bị cho cảnh hành động tiếp theo.', 'action', 'original', 'Action không đồng nghĩa với acting (diễn xuất); nghĩa học đã được đối chiếu Cambridge.', 'https://dictionary.cambridge.org/dictionary/english/action', '[]'),
('approach', '/əˈprəʊtʃ/', 'v', 'tiếp cận', 'Please approach the ticket desk if you need help finding your seat.', 'THEATER (RẠP PHIM)', 494, 'approach', 'Vui lòng đến quầy vé nếu bạn cần hỗ trợ tìm chỗ ngồi.', 'approach', 'original', null, null, '[{"term":"go up to","pos":"v","meaning_vi":"tiến đến gần","relation":"synonym","note_vi":null}]'),
('audience', '/ˈɔːdiəns/', 'n', 'khán giả', 'The audience applauded warmly when the musicians returned to the stage.', 'THEATER (RẠP PHIM)', 495, 'audience', 'Khán giả vỗ tay nồng nhiệt khi các nhạc công trở lại sân khấu.', 'audience', 'original', null, null, '[{"term":"spectators","pos":"n","meaning_vi":"khán giả","relation":"near","note_vi":"Spectators thường xem trực tiếp; audience bao gồm người nghe hoặc theo dõi phát sóng."}]'),
('creative', '/kriˈeɪ.tɪv/', 'adj', 'sáng tạo', 'The theater hired a creative designer to develop its new stage scenery.', 'THEATER (RẠP PHIM)', 496, 'creative', 'Nhà hát thuê một nhà thiết kế sáng tạo để phát triển cảnh trí sân khấu mới.', 'creative', 'original', null, null, '[{"term":"imaginative","pos":"adj","meaning_vi":"giàu trí tưởng tượng","relation":"synonym","note_vi":null}]'),
('dialogue', '/ˈdaɪəlɑːɡ/', 'n', 'cuộc đối thoại', 'The opening dialogue introduces the conflict between the two main characters.', 'THEATER (RẠP PHIM)', 497, 'dialogue', 'Đoạn đối thoại mở đầu giới thiệu mâu thuẫn giữa hai nhân vật chính.', 'dialogue', 'original', null, null, '[{"term":"conversation","pos":"n","meaning_vi":"cuộc đối thoại","relation":"synonym","note_vi":null}]'),
('element', '/ˈelɪmənt/', 'n', 'yếu tố', 'Lighting is an essential element of a successful live performance.', 'THEATER (RẠP PHIM)', 498, 'element', 'Ánh sáng là yếu tố thiết yếu của một buổi biểu diễn trực tiếp thành công.', 'element', 'original', null, null, '[{"term":"component","pos":"n","meaning_vi":"thành phần, yếu tố","relation":"synonym","note_vi":null}]'),
('experience', '/ɪkˈspɪriəns/', 'n', 'kinh nghiệm', 'Her experience in theater management helped her organize the charity performance.', 'THEATER (RẠP PHIM)', 499, 'experience', 'Kinh nghiệm quản lý nhà hát giúp cô ấy tổ chức buổi biểu diễn từ thiện.', 'experience', 'original', null, null, '[{"term":"expertise","pos":"n","meaning_vi":"chuyên môn","relation":"near","note_vi":"Expertise là kỹ năng chuyên sâu có được, experience nhấn mạnh quá trình từng làm."}]'),
('occur', '/əˈkɜːr/', 'v', 'diễn ra, xảy ra', 'Unexpected delays can occur when outdoor performances depend on the weather.', 'THEATER (RẠP PHIM)', 500, 'occur', 'Những chậm trễ bất ngờ có thể xảy ra khi buổi diễn ngoài trời phụ thuộc vào thời tiết.', 'occur', 'original', null, null, '[{"term":"happen","pos":"v","meaning_vi":"xảy ra","relation":"synonym","note_vi":null}]'),
('perform', '/pərˈfɔːrm/', 'v', 'biểu diễn, trình diễn', 'The orchestra will perform a new piece at the opening ceremony.', 'THEATER (RẠP PHIM)', 501, 'perform', 'Dàn nhạc sẽ biểu diễn một tác phẩm mới trong lễ khai mạc.', 'perform', 'original', null, null, '[{"term":"play","pos":"v","meaning_vi":"biểu diễn, chơi nhạc","relation":"near","note_vi":"Dùng cho biểu diễn nhạc trong ví dụ; không thay mọi loại biểu diễn."}]'),
('rehearse', '/rɪˈhɜːrs/', 'v', 'diễn tập', 'The actors will rehearse the final scene before the afternoon performance.', 'THEATER (RẠP PHIM)', 502, 'rehearse', 'Các diễn viên sẽ diễn tập cảnh cuối trước buổi biểu diễn chiều.', 'rehearse', 'original', null, null, '[{"term":"practice","pos":"v","meaning_vi":"luyện tập, diễn tập","relation":"near","note_vi":"Rehearse thường chuẩn bị cho buổi biểu diễn; practice rộng hơn."}]'),
('review', '/rɪˈvjuː/', 'n, v', 'bài phê bình (n) xem xét lại (v)', 'The newspaper published a favorable review of the theater''s new production.', 'THEATER (RẠP PHIM)', 503, 'review', 'Tờ báo đăng một bài phê bình tích cực về vở diễn mới của nhà hát.', 'review', 'original', null, null, '[{"term":"critique","pos":"n","meaning_vi":"bài phê bình","relation":"near","note_vi":"Critique thường phân tích chi tiết hơn một bài review ngắn."}]'),
('sell out', '/sel aʊt/', 'v', 'bán hết', 'Tickets for the weekend concert may sell out before Friday afternoon.', 'THEATER (RẠP PHIM)', 504, 'sell out', 'Vé cho buổi hòa nhạc cuối tuần có thể bán hết trước chiều thứ Sáu.', 'sell out', 'original', null, null, '[]'),
('available', '/əˈveɪləbl/', 'adj', 'sẵn có', 'A few seats are still available for tomorrow evening''s performance.', 'MUSIC (ÂM NHẠC)', 505, 'available', 'Một vài chỗ ngồi vẫn còn cho buổi biểu diễn tối mai.', 'available', 'original', null, null, '[{"term":"obtainable","pos":"adj","meaning_vi":"có thể có được","relation":"near","note_vi":"Obtainable nhấn mạnh khả năng kiếm hoặc mua được; available còn chỉ người rảnh."}]'),
('broaden', '/ˈbrɔːdn/', 'v', 'mở rộng', 'Reading international newspapers can broaden your understanding of overseas business practices.', 'MUSIC (ÂM NHẠC)', 506, 'broaden', 'Đọc báo quốc tế có thể mở rộng hiểu biết của bạn về cách kinh doanh ở nước ngoài.', 'broaden', 'original', null, null, '[{"term":"expand","pos":"v","meaning_vi":"mở rộng","relation":"synonym","note_vi":null}]'),
('categorize', '/ˈkætəɡəraɪz/', 'v', 'phân loại', 'The librarian will categorize the new books before placing them on shelves.', 'MUSIC (ÂM NHẠC)', 507, 'categorize', 'Thủ thư sẽ phân loại sách mới trước khi xếp chúng lên kệ.', 'categorize', 'original', null, null, '[{"term":"classify","pos":"v","meaning_vi":"phân loại","relation":"synonym","note_vi":null}]'),
('disparate', '/ˈdɪs.pɚ.ət/', 'adj', 'khác biệt hoàn toàn', 'The exhibition brings together artists from disparate cultural and professional backgrounds.', 'MUSIC (ÂM NHẠC)', 508, 'disparate', 'Triển lãm quy tụ các nghệ sĩ có nền tảng văn hóa và nghề nghiệp rất khác nhau.', 'disparate', 'original', null, null, '[{"term":"dissimilar","pos":"adj","meaning_vi":"khác nhau","relation":"near","note_vi":"Disparate nhấn mạnh khác biệt lớn hoặc khó so sánh; dissimilar nhẹ hơn."}]'),
('divide', '/dɪˈvaɪd/', 'v', 'phân chia', 'We can divide the reading list into fiction and business titles.', 'MUSIC (ÂM NHẠC)', 509, 'divide', 'Chúng ta có thể chia danh sách đọc thành sách hư cấu và sách kinh doanh.', 'divide', 'original', null, null, '[{"term":"split","pos":"v","meaning_vi":"chia, phân chia","relation":"synonym","note_vi":null}]'),
('favor', '/ˈfeɪvər/', 'v', 'ưu tiên hơn, ủng hộ hơn', 'Our customers tend to favor practical travel guides over large reference books.', 'MUSIC (ÂM NHẠC)', 510, 'favor', 'Khách của chúng tôi có xu hướng chuộng cẩm nang du lịch thiết thực hơn sách tham khảo lớn.', 'favor', 'original', null, null, '[{"term":"prefer","pos":"v","meaning_vi":"ưa chuộng hơn","relation":"synonym","note_vi":null}]'),
