('prefer', '/prɪˈfɜːr/', 'v', 'thích hơn', 'Many commuters prefer digital books because they are easy to carry.', 'MUSIC (ÂM NHẠC)', 512, 'prefer', 'Nhiều người đi làm thích sách điện tử hơn vì chúng dễ mang theo.', 'prefer', 'original', null, null, '[{"term":"favor","pos":"v","meaning_vi":"ưa chuộng hơn","relation":"synonym","note_vi":null}]'),
('reason', '/ˈriːzn/', 'n', 'lý do', 'The main reason for the delay was a shortage of printing paper.', 'MUSIC (ÂM NHẠC)', 513, 'reason', 'Lý do chính gây chậm trễ là thiếu giấy in.', 'reason', 'original', null, null, '[{"term":"cause","pos":"n","meaning_vi":"nguyên nhân","relation":"near","note_vi":"Cause chỉ nguyên nhân gây ra sự việc; reason cũng có thể là lý do biện minh."}]'),
('relaxation', '/ˌrilækˈseɪʃn/', 'n', 'sự thư giãn', 'The hotel library offers a peaceful space for relaxation after business meetings.', 'MUSIC (ÂM NHẠC)', 514, 'relaxation', 'Thư viện khách sạn cung cấp không gian yên bình để thư giãn sau các cuộc họp công việc.', 'relaxation', 'original', null, null, '[{"term":"rest","pos":"n","meaning_vi":"sự nghỉ ngơi","relation":"near","note_vi":"Rest thiên về nghỉ để hồi sức; relaxation nhấn mạnh giảm căng thẳng."}]'),
('taste', '/teɪst/', 'n', 'thị hiếu, gu (thẩm mỹ)', 'The bookstore stocks magazines to suit every reader''s taste and interests.', 'MUSIC (ÂM NHẠC)', 515, 'taste', 'Nhà sách có các tạp chí phù hợp với thị hiếu và sở thích của mọi độc giả.', 'taste', 'original', null, null, '[{"term":"preference","pos":"n","meaning_vi":"sở thích, thị hiếu","relation":"synonym","note_vi":null}]'),
