('admire', '/ədˈmaɪər/', 'v', 'ngưỡng mộ', 'Visitors can admire the restored ceiling during the guided museum tour.', 'MUSEUMS (BẢO TÀNG)', 518, 'admire', 'Du khách có thể chiêm ngưỡng trần nhà đã phục chế trong chuyến tham quan bảo tàng có hướng dẫn.', 'admire', 'original', null, null, '[{"term":"appreciate","pos":"v","meaning_vi":"trân trọng, thưởng thức","relation":"near","note_vi":"Trong ngữ cảnh chiêm ngưỡng vẻ đẹp; admire còn dùng cho ngưỡng mộ con người."}]'),
('collection', '/kəˈlɛkʃn/', 'n', 'bộ sưu tập', 'The museum''s permanent collection includes photographs of the city''s early factories.', 'MUSEUMS (BẢO TÀNG)', 519, 'collection', 'Bộ sưu tập thường trực của bảo tàng gồm những bức ảnh về các nhà máy thời kỳ đầu của thành phố.', 'collection', 'original', null, null, '[{"term":"assemblage","pos":"n","meaning_vi":"tập hợp hiện vật","relation":"near","note_vi":"Assemblage trang trọng hơn và không nhất thiết có chủ đích sưu tầm."}]'),
('criticism', '/ˈkrɪt̮əˌsɪzəm/', 'n', 'sự phê bình', 'The curator welcomed constructive criticism of the exhibition''s layout and lighting.', 'MUSEUMS (BẢO TÀNG)', 520, 'criticism', 'Người phụ trách hoan nghênh những góp ý mang tính xây dựng về bố cục và ánh sáng triển lãm.', 'criticism', 'original', null, null, '[{"term":"critique","pos":"n","meaning_vi":"sự phê bình","relation":"near","note_vi":"Critique thường là phân tích có hệ thống; criticism cũng có thể chỉ lời chê."}]'),
('fashion', '/ˈfæʃn/', 'n', 'thời trang', 'The exhibition traces changes in office fashion over the past century.', 'MUSEUMS (BẢO TÀNG)', 521, 'fashion', 'Triển lãm tìm hiểu những thay đổi của thời trang công sở trong thế kỷ qua.', 'fashion', 'original', null, null, '[{"term":"style","pos":"n","meaning_vi":"phong cách","relation":"near","note_vi":"Fashion nhấn mạnh xu hướng được ưa chuộng theo thời; style có thể riêng của cá nhân."}]'),
('leisure', '/ˈliːʒər/', 'n', 'thời gian rảnh', 'Conference guests can explore the museum at their leisure on Sunday.', 'MUSEUMS (BẢO TÀNG)', 522, 'leisure', 'Khách dự hội nghị có thể thong thả khám phá bảo tàng vào Chủ nhật.', 'leisure', 'original', null, null, '[{"term":"free time","pos":"n","meaning_vi":"thời gian rảnh","relation":"near","note_vi":"Không thay nguyên cụm at one''s leisure bằng at one''s free time."}]'),
('respond', '/rɪˈspɑːnd/', 'v', 'phản ứng lại', 'The museum will respond to visitor feedback before planning its next exhibition.', 'MUSEUMS (BẢO TÀNG)', 523, 'respond', 'Bảo tàng sẽ phản hồi ý kiến của khách trước khi lên kế hoạch cho triển lãm tiếp theo.', 'respond', 'original', null, null, '[{"term":"reply","pos":"v","meaning_vi":"trả lời","relation":"near","note_vi":"Reply dùng cho lời hồi đáp; respond còn chỉ phản ứng hoặc hành động đáp lại."}]'),
('schedule', '/ˈskedʒuːl/', 'n, v', 'lịch trình, kế hoạch (n) lên kế hoạch (v)', 'The tour schedule allows an hour for exploring the sculpture garden.', 'MUSEUMS (BẢO TÀNG)', 524, 'schedule', 'Lịch trình tham quan dành một giờ để khám phá vườn điêu khắc.', 'schedule', 'original', null, null, '[{"term":"timetable","pos":"n","meaning_vi":"thời gian biểu","relation":"synonym","note_vi":null}]'),
('significant', '/sɪɡˈnɪfɪkənt/', 'adj', 'quan trọng, có ý nghĩa', 'The donation made a significant contribution to the museum''s restoration project.', 'MUSEUMS (BẢO TÀNG)', 525, 'significant', 'Khoản quyên góp có đóng góp quan trọng cho dự án phục chế của bảo tàng.', 'significant', 'original', null, null, '[{"term":"important","pos":"adj","meaning_vi":"quan trọng","relation":"synonym","note_vi":null}]'),
