('emphasize', '/ˈemfəsaɪz/', 'v', 'nhấn mạnh', 'The trainer will emphasize the importance of submitting accurate insurance forms.', 'HEALTH INSURANCE (BẢO HIỂM SỨC KHỎE)', 566, 'emphasize', 'Người đào tạo sẽ nhấn mạnh tầm quan trọng của việc nộp biểu mẫu bảo hiểm chính xác.', 'emphasize', 'original', null, null, '[{"term":"stress","pos":"v","meaning_vi":"nhấn mạnh","relation":"synonym","note_vi":null}]'),
