('personnel', '/ˌpɜːrsəˈnel/', 'n', 'nhân sự', 'The personnel department can answer questions about your health insurance benefits.', 'HEALTH INSURANCE (BẢO HIỂM SỨC KHỎE)', 568, 'personnel', 'Bộ phận nhân sự có thể trả lời các câu hỏi về quyền lợi bảo hiểm sức khỏe của bạn.', 'personnel', 'original', null, null, '[{"term":"staff","pos":"n","meaning_vi":"nhân viên","relation":"synonym","note_vi":null}]'),
('policy', '/ˈpɑːləsi/', 'n', 'chính sách', 'Please read the company''s policy on medical leave before submitting your request.', 'HEALTH INSURANCE (BẢO HIỂM SỨC KHỎE)', 569, 'policy', 'Vui lòng đọc chính sách nghỉ phép vì sức khỏe của công ty trước khi nộp yêu cầu.', 'policy', 'original', null, null, '[{"term":"rule","pos":"n","meaning_vi":"quy định","relation":"near","note_vi":"Policy thường là định hướng hoặc bộ nguyên tắc; rule là quy định cụ thể."}]'),
('portion', '/ˈpɔːrʃn/', 'n', 'phần', 'Employees pay a small portion of the monthly insurance premium.', 'HEALTH INSURANCE (BẢO HIỂM SỨC KHỎE)', 570, 'portion', 'Nhân viên trả một phần nhỏ phí bảo hiểm hằng tháng.', 'portion', 'original', null, null, '[{"term":"part","pos":"n","meaning_vi":"phần","relation":"synonym","note_vi":null}]'),
('regardless', '/rɪˈɡɑrdləs/', 'adv', 'bất chấp', 'All staff receive the same coverage regardless of their job title.', 'HEALTH INSURANCE (BẢO HIỂM SỨC KHỎE)', 571, 'regardless', 'Mọi nhân viên đều được hưởng phạm vi bảo hiểm như nhau bất kể chức danh.', 'regardless', 'original', null, null, '[]'),
('reimburse', '/ˌriːɪmˈbɜːrs/', 'v', 'hoàn trả', 'The company will reimburse employees for approved travel expenses next week.', 'HEALTH INSURANCE (BẢO HIỂM SỨC KHỎE)', 572, 'reimburse', 'Công ty sẽ hoàn trả cho nhân viên các chi phí đi lại đã được duyệt vào tuần tới.', 'reimburse', 'original', null, null, '[{"term":"repay","pos":"v","meaning_vi":"hoàn trả","relation":"near","note_vi":"Reimburse thường hoàn chi phí đã trả hộ; repay còn dùng trả nợ."}]'),
