('permission', '/pərˈmɪʃn/', 'n', 'sự chấp thuận', 'The photographer obtained permission before taking pictures inside the hospital.', 'HOSPITALS (BỆNH VIỆN)', 581, 'permission', 'Nhiếp ảnh gia đã được cho phép trước khi chụp ảnh bên trong bệnh viện.', 'permission', 'original', null, null, '[{"term":"authorization","pos":"n","meaning_vi":"sự cho phép","relation":"synonym","note_vi":null}]'),
