('potential', '/pəˈtenʃl/', 'adj', 'tiềm năng', 'The supplier contacted potential customers before launching its new delivery service.', 'PHARMACY (HIỆU THUỐC)', 593, 'potential', 'Nhà cung cấp liên hệ các khách hàng tiềm năng trước khi ra mắt dịch vụ giao hàng mới.', 'potential', 'original', null, null, '[{"term":"prospective","pos":"adj","meaning_vi":"tiềm năng, có thể trở thành","relation":"synonym","note_vi":null}]'),
('sample', '/ˈsæmpl/', 'n', 'mẫu thử', 'The supplier left a sample of the new packaging for inspection.', 'PHARMACY (HIỆU THUỐC)', 594, 'sample', 'Nhà cung cấp để lại một mẫu bao bì mới để kiểm tra.', 'sample', 'original', null, null, '[{"term":"specimen","pos":"n","meaning_vi":"mẫu","relation":"near","note_vi":"Specimen thường là mẫu đại diện hoặc mẫu xét nghiệm; sample rộng hơn, gồm cả hàng dùng thử."}]'),
('sense', '/sens/', 'n', 'khả năng phán đoán', 'Her good sense helped the team avoid an expensive purchasing mistake.', 'PHARMACY (HIỆU THUỐC)', 595, 'sense', 'Khả năng phán đoán tốt của cô ấy giúp cả đội tránh một sai lầm mua hàng tốn kém.', 'sense', 'original', null, null, '[{"term":"judgment","pos":"n","meaning_vi":"khả năng phán đoán","relation":"near","note_vi":"Dùng trong good sense; sense còn nhiều nghĩa khác như giác quan."}]'),
('volunteer', '/ˌvɑː.lənˈtɪr/', 'v, n', 'tình nguyện (v) tình nguyện viên (n)', 'Employees can volunteer to help organize the hospital''s annual fundraising event.', 'PHARMACY (HIỆU THUỐC)', 596, 'volunteer', 'Nhân viên có thể tình nguyện hỗ trợ tổ chức sự kiện gây quỹ hằng năm của bệnh viện.', 'volunteer', 'original', null, null, '[{"term":"offer to help","pos":"v","meaning_vi":"tình nguyện giúp","relation":"near","note_vi":"Cần chỉnh câu khi đã có to help sau volunteer để tránh lặp."}]')
